  266:   Future<void> _createDownload(BiliDownloadEntryInfo entry) async {
  267:     final entryDir = await _getDownloadEntryDir(entry);
  268:     final entryJsonFile = File(path.join(entryDir.path, _entryFile));
  269:     await entryJsonFile.writeAsString(jsonEncode(entry.toJson()));
  270:     entry
  271:       ..pageDirPath = entryDir.parent.path
  272:       ..entryDirPath = entryDir.path
  273:       ..status = DownloadStatus.wait;
