  280:   Future<Directory> _getDownloadEntryDir(BiliDownloadEntryInfo entry) async {
  281:     late final String dirName;
  282:     late final String pageDirName;
  283:     if (entry.ep case final ep?) {
  284:       dirName = 's_${entry.seasonId}';
  285:       pageDirName = ep.episodeId.toString();
  286:     } else if (entry.pageData case final page?) {
  287:       dirName = entry.avid.toString();
  288:       pageDirName = 'c_${page.cid}';
  289:     }
  290:     final root = await _getDownloadPath();
  291:     // an export made before exports avoided internal names (e.g. a title
  292:     // "114514") may already occupy this video's page folder: move it aside
  293:     // so the download is not created inside it (and deleting the download
  294:     // cannot take the export with it)
  295:     final page = Directory(path.join(root, dirName));
  296:     if (page.existsSync() &&
  297:         _isForeignFolder(page) &&
  298:         // already holds downloads (made before this guard): leave it, the
  299:         // deletion guard keeps the export's files
  300:         !page.listSync().any(
  301:           (e) =>
  302:               e is Directory &&
  303:               File(path.join(e.path, _entryFile)).existsSync(),
  304:         )) {
  305:       var aside = exportFolderName(dirName);
  306:       for (var i = 2; Directory(path.join(root, aside)).existsSync(); i++) {
  307:         aside = '${exportFolderName(dirName)} ($i)';
  308:       }
  309:       final moved = path.join(root, aside);
  310:       try {
  311:         await page.rename(moved);
  312:         // the download that exported it still points at the old place
  313:         for (final e in downloadList) {
  314:           if (e.mergedPath case final merged?
  315:               when path.isWithin(page.path, merged)) {
  316:             e.mergedPath = path.join(
  317:               moved,
  318:               path.relative(merged, from: page.path),
  319:             );
  320:             await _updateBiliDownloadEntryJson(e);
  321:           }
  322:         }
  323:       } on FileSystemException catch (e) {
  324:         // e.g. Windows: a file in it is open (the export is playing). The
  325:         // download goes inside it then; the deletion guards on both sides
  326:         // keep the export's files and the download apart.
  327:         if (kDebugMode) debugPrint('cannot move export aside: $e');
  328:       }
  329:     }
  330:     final pageDir = Directory(path.join(root, dirName, pageDirName));
  331:     if (!pageDir.existsSync()) {
  332:       await pageDir.create(recursive: true);
  333:     }
  334:     return pageDir;
  335:   }
