  345:   Future<void> startDownload(BiliDownloadEntryInfo entry) {
  346:     // already finished downloading; the merge completes it
  347:     if (_mergingCids.contains(entry.cid)) return Future.value();
  348:     return _lock.synchronized(() async {
  349:       await _downloadManager?.cancel(isDelete: false);
  350:       await _audioDownloadManager?.cancel(isDelete: false);
  351:       _downloadManager = null;
  352:       _audioDownloadManager = null;
  353:       if (curDownload.value case final curEntry?) {
  354:         if (curEntry.status.isDownloading) {
  355:           curEntry.status = DownloadStatus.pause;
  356:         }
  357:       }
  358: 
  359:       _curCid = entry.cid;
  360:       curDownload.value = entry;
  361:       waitDownloadQueue.refresh();
  362:       await _startDownload(entry);
  363:     });
  364:   }
