  366:   Future<bool> downloadDanmaku({
  367:     required BiliDownloadEntryInfo entry,
  368:     bool isUpdate = false,
  369:   }) async {
  370:     final cid = entry.pageData?.cid ?? entry.source?.cid;
  371:     if (cid == null) {
  372:       return false;
  373:     }
  374:     final danmakuFile = File(
  375:       path.join(entry.entryDirPath, PathUtils.danmakuName),
  376:     );
  377:     if (isUpdate || !danmakuFile.existsSync()) {
  378:       try {
  379:         if (!isUpdate) {
  380:           _updateCurStatus(DownloadStatus.getDanmaku);
  381:         }
  382:         // unknown duration: at least the first segment
  383:         final seg = math.max(
  384:           (entry.totalTimeMilli / DmUtils.segLength).ceil(),
  385:           1,
  386:         );
  387: 
  388:         final danmaku = (await DmGrpc.dmSegMobile(
  389:           cid: cid,
  390:           segmentIndex: 1,
  391:         )).data;
  392:         for (var start = 2; start <= seg; start += _maxDanmakuConcurrency) {
  393:           final end = start + _maxDanmakuConcurrency - 1;
  394:           final responses = await Future.wait([
  395:             for (var index = start; index <= seg && index <= end; index++)
  396:               DmGrpc.dmSegMobile(cid: cid, segmentIndex: index),
  397:           ]);
  398:           for (final response in responses) {
  399:             danmaku.elems.addAll(response.data.elems);
  400:           }
  401:           responses.clear();
  402:         }
  403:         await danmakuFile.writeAsBytes(danmaku.writeToBuffer());
  404: 
  405:         return true;
  406:       } catch (e) {
  407:         if (!isUpdate) {
  408:           _updateCurStatus(DownloadStatus.failDanmaku);
  409:         }
  410:         if (kDebugMode) SmartDialog.showToast(e.toString());
  411:         return false;
  412:       }
  413:     }
  414:     return true;
  415:   }
