  439:   Future<void> _startDownload(BiliDownloadEntryInfo entry) async {
  440:     try {
  441:       // danmaku is optional: a failed fetch must not block the video (it
  442:       // can be fetched again later with "update danmaku")
  443:       await downloadDanmaku(entry: entry);
  444: 
  445:       _updateCurStatus(DownloadStatus.getPlayUrl);
  446: 
  447:       final oldTypeTag = entry.typeTag;
  448:       final mediaFileInfo = await DownloadHttp.getVideoUrl(
  449:         entry: entry,
  450:         ep: entry.ep,
  451:         source: entry.source,
  452:         pageData: entry.pageData,
  453:       );
  454: 
  455:       // the stream is picked again on every start (codec / login / quality
  456:       // settings may have changed): partial files of another stream must
  457:       // not be resumed, or two streams end up in one file
  458:       if (oldTypeTag != entry.typeTag) {
  459:         await Directory(
  460:           path.join(entry.entryDirPath, oldTypeTag),
  461:         ).tryDel(recursive: true);
  462:       }
  463:       final videoDir = Directory(path.join(entry.entryDirPath, entry.typeTag));
  464:       final mediaJsonFile = File(path.join(videoDir.path, _indexFile));
  465:       if (videoDir.existsSync()) {
  466:         String? oldKey;
  467:         try {
  468:           oldKey = _streamKey(jsonDecode(await mediaJsonFile.readAsString()));
  469:         } catch (_) {}
  470:         if (oldKey != _streamKey(mediaFileInfo.toJson())) {
  471:           await videoDir.tryDel(recursive: true);
  472:         }
  473:       }
  474:       if (!videoDir.existsSync()) {
  475:         await videoDir.create(recursive: true);
  476:       }
  477: 
  478:       await Future.wait([
  479:         mediaJsonFile.writeAsString(jsonEncode(mediaFileInfo.toJson())),
  480:         _downloadCover(entry: entry),
  481:       ]);
  482: 
  483:       if (curDownload.value?.cid != entry.cid) {
  484:         return;
  485:       }
  486: 
  487:       switch (mediaFileInfo) {
  488:         case Type1 mediaFileInfo:
  489:           _startSegment(mediaFileInfo.segmentList, 0, videoDir.path);
  490:           break;
  491:         case Type2 mediaFileInfo:
  492:           _downloadManager = DownloadManager(
  493:             url: mediaFileInfo.video.first.baseUrl,
  494:             backupUrls: mediaFileInfo.video.first.backupUrl ?? const [],
  495:             path: path.join(videoDir.path, PathUtils.videoNameType2),
  496:             onReceiveProgress: _onReceive,
  497:             onDone: _onDone,
  498:           );
  499:           final audio = mediaFileInfo.audio;
  500:           if (audio != null && audio.isNotEmpty) {
  501:             _audioDownloadManager = DownloadManager(
  502:               url: audio.first.baseUrl,
  503:               backupUrls: audio.first.backupUrl ?? const [],
  504:               path: path.join(videoDir.path, PathUtils.audioNameType2),
  505:               onReceiveProgress: null,
  506:               onDone: _onAudioDone,
  507:             );
  508:           }
  509:           late final first = mediaFileInfo.video.first;
  510:           entry.pageData
  511:             ?..width = first.width
  512:             ..height = first.height;
  513:           entry.ep
  514:             ?..width = first.width
  515:             ..height = first.height;
  516:           _updateBiliDownloadEntryJson(entry);
  517:           break;
  518:         default:
  519:           break;
  520:       }
  521:     } catch (e) {
  522:       _updateCurStatus(DownloadStatus.failPlayUrl);
  523:       if (kDebugMode) {
  524:         debugPrint('get download url error: $e');
  525:       }
  526:     }
  527:   }
  528: 
  529:   /// What identifies the bytes of a saved stream ([_indexFile] json): the
  530:   /// dash video / audio stream picked, or the durl segment sizes.
  531:   static String? _streamKey(Object? json) {
  532:     if (json is! Map) return null;
  533:     String file(Object? list) {
  534:       if (list is! List || list.isEmpty || list.first is! Map) return '';
  535:       final f = list.first as Map;
  536:       return '${f['id']}/${f['codecid']}/${f['width']}x${f['height']}';
  537:     }
  538: 
  539:     if (json['video'] != null) {
  540:       return 'dash:${file(json['video'])}:${file(json['audio'])}';
  541:     }
  542:     if (json['segment_list'] case final List segments) {
  543:       return 'durl:${segments.map((e) => e is Map ? e['bytes'] : null).join(',')}';
  544:     }
  545:     return null;
  546:   }
  547: 
  548:   /// Old single-URL (durl) streams may come in several segments: they are
  549:   /// downloaded one after another (resuming what is on disk) and joined by
  550:   /// [_mergeDownload]. Progress runs over their total size.
  551:   void _startSegment(List<Type1Segment> segments, int index, String dir) {
  552:     final total = segments.fold<int>(0, (s, e) => s + e.bytes);
  553:     final done = segments.take(index).fold<int>(0, (s, e) => s + e.bytes);
  554:     final segment = segments[index];
  555:     late final DownloadManager manager;
  556:     manager = DownloadManager(
  557:       url: segment.url,
  558:       backupUrls: segment.backupUrls,
  559:       path: path.join(dir, PathUtils.segmentNameType1(index)),
  560:       onReceiveProgress: segments.length == 1 || total <= 0
  561:           ? _onReceive
  562:           : (received, _) => _onReceive(done + received, total),
  563:       onDone: ([error]) {
  564:         if (error != null || index + 1 == segments.length) {
  565:           return _onDone(error);
  566:         }
  567:         // paused / deleted / replaced meanwhile
  568:         if (!identical(_downloadManager, manager)) return;
  569:         _startSegment(segments, index + 1, dir);
  570:       },
  571:     );
  572:     _downloadManager = manager;
  573:   }
