  575:   Future<void> _updateBiliDownloadEntryJson(BiliDownloadEntryInfo entry) {
  576:     final entryJsonFile = File(path.join(entry.entryDirPath, _entryFile));
  577:     return entryJsonFile.writeAsString(jsonEncode(entry.toJson()));
  578:   }
  579: 
  580:   void _onReceive(int progress, int total) {
  581:     if (curDownload.value case final entry?) {
  582:       if (progress == 0 && total != 0) {
  583:         _updateBiliDownloadEntryJson(entry..totalBytes = total);
  584:       }
  585:       entry
  586:         ..downloadedBytes = progress
  587:         ..status = DownloadStatus.downloading;
  588:       curDownload.refresh();
  589:     }
  590:   }
