  592:   /// Last download error (diagnostics: self test, logs).
  593:   String? lastError;
  594: 
  595:   void _onDone([Object? error]) {
  596:     if (error != null) {
  597:       lastError = 'video: $error';
  598:       debugPrint('download failed: $lastError');
  599:     }
  600:     if (error != null) {
  601:       _updateCurStatus(_downloadManager?.status ?? DownloadStatus.pause);
  602:       return;
  603:     }
  604: 
  605:     final status = switch (_audioDownloadManager?.status) {
