      return true;
    }
    // reads scoped to the user themself (own space, own followings...)
    final mid = Accounts.main.mid;
    if (mid != 0) {
      for (final key in _selfKeys) {
        final v = query[key] ?? (data is Map ? data[key] : null);
        if (v != null && '$v' == '$mid') return true;
      }
    }
    return false;
  }
}

