import 'dart:async' show FutureOr;
import 'dart:io' show Platform;

import 'package:PiliPlus/http/loading_state.dart';
import 'package:PiliPlus/http/user.dart';
import 'package:PiliPlus/main.dart' show webViewEnvironment;
import 'package:PiliPlus/services/account_service.dart';
import 'package:PiliPlus/utils/accounts.dart';
import 'package:PiliPlus/utils/accounts/account.dart';
import 'package:PiliPlus/utils/request_utils.dart';
import 'package:PiliPlus/utils/storage.dart';
import 'package:PiliPlus/utils/storage_pref.dart';
import 'package:PiliPlus/utils/utils.dart';
import 'package:collection/collection.dart';
import 'package:PiliPlus/utils/linux_cookie_manager.dart';
import 'package:crypto/crypto.dart' show Digest;
import 'package:flutter_inappwebview/flutter_inappwebview.dart' as web;
import 'package:flutter_smart_dialog/flutter_smart_dialog.dart';
import 'package:get/get.dart';

abstract final class LoginUtils {
  static FutureOr setWebCookie([Account? account]) {
    if (Platform.isLinux) return null;
    final cookies = (account ?? Accounts.main).cookieJar.toList();
    final webManager = web.CookieManager.instance(
      webViewEnvironment: webViewEnvironment,
    );
    return Future.wait(
      cookies.map(
        (cookie) => webManager.setCookie(
          url: web.WebUri(
            '${Platform.isWindows ? 'https://' : ''}${cookie.domain}',
          ),
          name: cookie.name,
          value: cookie.value,
          path: cookie.path ?? '/',
          domain: cookie.domain,
          isSecure: cookie.secure,
          isHttpOnly: cookie.httpOnly,
        ),
      ),
    );
  }

  /// LibrePili: pages in the in-app WebView are anonymous. Removes the stored
  /// accounts' cookies (e.g. installed by an older build) and installs the
  /// anonymous jar; account cookies go in only for explicit account flows
  /// (the "reset cookie" menu, taking notes).
  static FutureOr setAnonymousWebCookie() async {
    if (Platform.isLinux) return null;
    final webManager = web.CookieManager.instance(
      webViewEnvironment: webViewEnvironment,
    );
    await Future.wait([
      for (final account in Accounts.account.values)
        for (final cookie in account.cookieJar.toList())
          webManager.deleteCookie(
            url: web.WebUri(
              '${Platform.isWindows ? 'https://' : ''}${cookie.domain}',
            ),
            name: cookie.name,
            path: cookie.path ?? '/',
            domain: cookie.domain,
          ),
    ]);
    return setWebCookie(AnonymousAccount());
  }

  /// Removes every cookie from the in-app WebView store (used when all data
  /// is reset, so a deleted account's session does not survive there).
  static Future<void> clearWebCookies() async {
    try {
      if (Platform.isLinux) {
        await LinuxCookieManager.deleteAllCookies();
      } else {
        await web.CookieManager.instance(
          webViewEnvironment: webViewEnvironment,
        ).deleteAllCookies();
      }
    } catch (_) {}
  }

  static Future<void> onLoginMain() async {
    final account = Accounts.main;
    final res = await UserHttp.userInfo();
    if (res case Success(:final response)) {
      setAnonymousWebCookie();
      RequestUtils.syncHistoryStatus();
      if (response.isLogin == true) {
        final accountService = Get.find<AccountService>()
          ..face.value = response.face!;

        if (accountService.isLogin.value) {
          accountService.isLogin.refresh();
        } else {
          accountService.isLogin.value = true;
        }

        SmartDialog.showToast('main登录成功');
        if (response != Pref.userInfoCache) {
          await GStorage.userInfo.put('userInfoCache', response);
        }
      }
    } else {
      // 获取用户信息失败
      final errMsg = res.toString();
      if (errMsg == '账号未登录') {
        // kept (marked expired), so one bad answer cannot delete it
        if (account is LoginAccount) await Accounts.markExpired({account});
        SmartDialog.showNotify(
          msg: '账号登录已失效（$errMsg），可在「账号切换」中重新登录或删除',
          notifyType: .warning,
        );
      } else {
        SmartDialog.showToast(errMsg);
      }
    }
  }

  static Future<void> onLogoutMain() {
    Get.find<AccountService>()
      ..face.value = ''
      ..isLogin.value = false;

    return Future.wait([
      if (Platform.isLinux)
        LinuxCookieManager.deleteAllCookies()
      else
        // an empty jar is not anonymous: put the anonymous buvid3 back, or
        // every WebView page for the rest of the session looks like a bot
        web.CookieManager.instance(webViewEnvironment: webViewEnvironment)
            .deleteAllCookies()
            .then((_) => setAnonymousWebCookie()),
      GStorage.userInfo.delete('userInfoCache'),
    ]);
  }

  static String generateBuvid() {
    final md5Str = Digest(
      List.generate(16, (_) => Utils.random.nextInt(256)),
    ).toString();
    return 'XY${md5Str[2]}${md5Str[12]}${md5Str[22]}$md5Str';
  }

  /// Persistent device id: only for requests that carry the account.
  static final buvid = Pref.buvid;

  /// LibrePili: fresh device id per launch for anonymous requests, so they
  /// cannot be linked across launches or to the logged-in account.
  static final sessionBuvid = generateBuvid();

  // static String getUUID() {
  //   return const Uuid().v4().replaceAll('-', '');
  // }

  // static String generateBuvid() {
  //   String uuid = getUUID() + getUUID();
  //   return 'XY${uuid.substring(0, 35).toUpperCase()}';
  // }

  static String genDeviceId() {
    // https://github.com/bilive/bilive_client/blob/2873de0532c54832f5464a4c57325ad9af8b8698/bilive/lib/app_client.ts#L62
    final time = DateTime.now();

    final List<int> bytes = [
      ...Iterable.generate(16, (_) => Utils.random.nextInt(256)),
      _dec2bcd(time.year ~/ 100),
      _dec2bcd(time.year % 100),
      _dec2bcd(time.month),
      _dec2bcd(time.day),
      _dec2bcd(time.hour),
      _dec2bcd(time.minute),
      _dec2bcd(time.second),
      ...Iterable.generate(8, (_) => Utils.random.nextInt(256)),
    ];
    final check = (bytes.sum & 0xFF).toRadixString(16).padLeft(2, '0');

    return Digest(bytes).toString() + check;
  }

  static int _dec2bcd(int dec) {
    assert(0 <= dec && dec < 100);
    return ((dec ~/ 10) << 4) | (dec % 10);
  }
}

