              TextFormField(
                autofocus: true,
                initialValue: editValue,
                textInputAction: TextInputAction.newline,
                minLines: 1,
                maxLines: 4,
                onChanged: (value) => editValue = value,
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: Get.back,
              child: Text(
                '取消',
                style: TextStyle(color: ColorScheme.of(context).outline),
              ),
