                Get.back();
                banWord = editValue;
                setState();
                onChanged(RegExp(banWord, caseSensitive: false));
                SmartDialog.showToast('已保存');
                GStorage.setting.put(key, banWord);
              },
            ),
          ],
        ),
      );
    },
  );
}

