51	    // same as uriLinkStream, plus files opened while already running
52	    listener = appLinks.stringLinkStream.listen((link) {
53	      if (link.startsWith(_openFilePrefix)) {
54	        _openFile(link.substring(_openFilePrefix.length));
55	      } else if (_localFile(link) case final file?) {
56	        // Linux delivers command-line arguments (file paths) as links; the
57	        // file the app was launched with is already opened by main()
58	        if (file == launchFile) {
