static bool _isBlockServer(String path) {
  // match host *and* path prefix: a host-only match on a blockServer set to
  // a bilibili host (`https://api.bilibili.com/sb`) would strip the cookies
  // off every API request. A raw prefix match is not enough either: an
  // empty or too short saved address would match everything.
  final server = Uri.tryParse(blockServer);
  final host = server?.host;
  if (host == null || host.isEmpty) return false;
  final uri = Uri.tryParse(path);
  if (uri == null || uri.host.toLowerCase() != host.toLowerCase()) {
    return false;
  }
  final prefix = server!.path.replaceAll(RegExp(r'/+$'), '');
  return prefix.isEmpty ||
      uri.path == prefix ||
      uri.path.startsWith('$prefix/');
}

