5	class RetryInterceptor extends Interceptor {
6	  final Dio _client;
7	  final int _count;
8	  final int _delay;
9	
10	  RetryInterceptor(this._client, this._count, this._delay);
11	
12	  @override
13	  void onError(DioException err, ErrorInterceptorHandler handler) {
14	    if (err.requestOptions.responseType == ResponseType.stream) {
15	      return handler.next(err);
16	    }
17	    if (err.response != null) {
18	      final options = err.requestOptions;
19	      if (options.followRedirects && options.maxRedirects > 0) {
20	        final status = err.response!.statusCode;
21	        if (status != null && 300 <= status && status < 400) {
22	          var redirectUrl = err.response!.headers.value('location');
23	          if (redirectUrl != null) {
24	            final oldUri = options.uri;
25	            var uri = Uri.parse(redirectUrl);
26	            if (!uri.hasScheme) {
27	              uri = oldUri.resolveUri(uri);
28	              redirectUrl = uri.toString();
29	            }
30	            if (uri.scheme != oldUri.scheme ||
31	                uri.host != oldUri.host ||
32	                uri.port != oldUri.port) {
33	              // another origin gets neither the account's cookies nor its
34	              // headers, nor the old query (access_key...): the location
35	              // carries its own
36	              options
37	                ..queryParameters = {}
38	                // every gRPC header too: x-bili-metadata-bin starts with the
39	                // accessKey, x-bili-device-bin/buvid carry the persistent
40	                // device id, and the referer names where we came from
41	                ..headers.removeWhere((key, _) {
42	                  final name = key.toLowerCase();
43	                  return name.startsWith('x-bili-') ||
44	                      name == 'cookie' ||
45	                      name == 'authorization' ||
46	                      name == 'buvid' ||
47	                      name == 'referer';
48	                })
49	                ..extra['account'] = const NoAccount();
50	              // 307/308 (and a POST this interceptor follows itself) keep
51	              // the body: take the account's secrets out of it too
52	              _scrubBody(options);
53	            }
54	            (options..path = redirectUrl).maxRedirects--;
55	            if (status == 303) {
56	              options
57	                ..data = null
58	                ..method = 'GET';
59	            }
60	            _client
61	                .fetch(options)
62	                .then(
63	                  (i) => handler.resolve(
64	                    i
65	                      ..redirects.add(
66	                        RedirectRecord(status, options.method, uri),
67	                      )
68	                      ..isRedirect = true,
69	                  ),
70	                )
71	                .onError<DioException>((error, _) => handler.next(error));
72	            return;
73	          }
74	        }
75	      }
76	      return handler.next(err);
77	    } else {
78	      switch (err.type) {
79	        case DioExceptionType.connectionError:
80	        case DioExceptionType.connectionTimeout:
