  295:   static int _intStrDescKeyComparator(dynamic k1, dynamic k2) {
  296:     if (k1 is int) {
  297:       if (k2 is int) {
  298:         return k2.compareTo(k1);
  299:       } else {
  300:         return -1;
  301:       }
  302:     } else if (k2 is String) {
  303:       final lenCompare = k2.length.compareTo((k1 as String).length);
