    9: 
   10: abstract final class CacheManager {
   11:   static late final DefaultCacheManager manager;
   12: 
   13:   static Future<void> ensureInitialized() => DefaultCacheManager.init(
   14:     maxNrOfCacheLength: Pref.maxCacheSize.toInt(),
   15:     cacheDirectoryProvider: appTempDirectory,
   16:   ).then((i) => manager = i);
   17: 
   18:   // 获取缓存目录
   19:   @pragma('vm:notify-debugger-on-exception')
   20:   static Future<int> loadApplicationCache() async {
   21:     try {
   22:       if (PlatformUtils.isDesktop) {
   23:         return manager.getTotalLength();
   24:       }
   25: 
   26:       final Directory tempDirectory = await getTemporaryDirectory();
   27:       if (tempDirectory.existsSync()) {
   28:         return await getTotalSizeOfFilesInDir(tempDirectory);
   29:       }
   30:     } catch (_) {}
   31:     return 0;
   32:   }
   33: 
   34:   // 循环计算文件的大小
   35:   @pragma('vm:notify-debugger-on-exception')
   36:   static Future<int> getTotalSizeOfFilesInDir(Directory file) async {
   37:     int total = 0;
   38:     await for (final child in file.list(recursive: false)) {
   39:       if (child is File) {
   40:         total += await child.length();
   41:       } else if (child is Directory) {
   42:         if (path.equals(child.path, manager.cacheDir)) {
   43:           total += manager.getTotalLength();
   44:         } else {
   45:           await for (final i in child.list(recursive: true)) {
   46:             if (i is File) {
   47:               total += await i.length();
   48:             }
   49:           }
   50:         }
   51:       }
   52:     }
   53:     return total;
   54:   }
   55: 
   56:   // 缓存大小格式转换
   57:   static String formatSize(num value) {
   58:     const unitArr = ['B', 'K', 'M', 'G', 'T', 'P'];
   59:     int index = 0;
   60:     while (value >= 1024) {
   61:       index++;
   62:       value = value / 1024;
   63:     }
   64:     String size = value.toStringAsFixed(2);
   65:     return size + (unitArr.elementAtOrNull(index) ?? '');
   66:   }
   67: 
   68:   // 清除 Library/Caches 目录及文件缓存
   69:   @pragma('vm:notify-debugger-on-exception')
   70:   static Future<void> clearLibraryCache() async {
   71:     try {
   72:       await manager.emptyCache();
   73:       if (PlatformUtils.isDesktop) return;
   74: 
   75:       final tempDirectory = await getTemporaryDirectory();
   76:       if (tempDirectory.existsSync()) {
   77:         await for (final file in tempDirectory.list(recursive: false)) {
   78:           // this app's own folder: its image cache was emptied above, and
   79:           // the rest is scratch a running task may still be holding (share
   80:           // / export / remux files, side files of a local video). Everything
   81:           // else here belongs to plugins and is cache proper.
   82:           if (path.equals(file.path, tmpDirPath) ||
   83:               path.isWithin(file.path, tmpDirPath)) {
   84:             continue;
   85:           }
   86:           await file.delete(recursive: true);
   87:         }
   88:       }
   89:     } catch (_) {}
   90:   }
   91: }
--- macos/Runner/AppDelegate.swift
    1: import Cocoa
    2: import FlutterMacOS
    3: import app_links
    4: 
    5: @main
    6: class AppDelegate: FlutterAppDelegate {
    7:   override func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
    8:     return false
    9:   }
   10: 
   11:   /// "Open with" (see CFBundleDocumentTypes in Info.plist): Finder sends the
   12:   /// file as a `file:` url here. `FlutterAppDelegate` only offers these to
   13:   /// plugins implementing `handleOpenURLs:`, and app_links implements none
   14:   /// (it claims kAEGetURL for custom schemes instead), so they would be
   15:   /// dropped. Feeding them into app_links' own stream is what the Dart side
   16:   /// already expects: `PiliScheme.init` turns a `file:` link into a path and
   17:   /// opens it with `LocalPlayer` (the same path Linux takes). A url received
   18:   /// before the engine is up is replayed to the first subscriber.
   19:   override func application(_ application: NSApplication, open urls: [URL]) {
   20:     let files = urls.filter { $0.isFileURL }
   21:     let others = urls.filter { !$0.isFileURL }
   22:     if !others.isEmpty {
   23:       super.application(application, open: others)
   24:     }
   25:     for url in files {
   26:       AppLinks.shared.handleLink(link: url.absoluteString)
   27:     }
   28:   }
   29: 
   30:   override func applicationSupportsSecureRestorableState(_ app: NSApplication) -> Bool {
   31:     return true
   32:   }
   33: 
   34:   override func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
   35:     if !flag {
   36:       for window in NSApp.windows {
   37:         if !window.isVisible {
   38:           window.setIsVisible(true)
   39:         }
   40:         window.makeKeyAndOrderFront(self)
   41:         NSApp.activate(ignoringOtherApps: true)
   42:       }
   43:     }
   44:     return true
   45:   }
   46: }
