   92: 
   93:   static const _csrfKeys = {'csrf', 'biliCSRF', 'csrf_token'};
   94:   static const _selfKeys = ['mid', 'vmid', 'up_mid'];
   95: 
   96:   /// Whether UI that writes (comments, replies, danmaku, live chat) is
   97:   /// shown: it needs a logged-in account and the "hide interaction" switch
   98:   /// off. Existing comments and danmaku are displayed either way.
   99:   static bool get canInteract => Accounts.main.isLogin && !Pref.hideInteraction;
  100: 
  101:   /// `options.extra[explicitAccount] = true`: the call site must go out as
  102:   /// the account it passed in `extra['account']` although the path is not
  103:   /// on the lists (e.g. the comment check's "seen as the account" half,
  104:   /// compared with an anonymous request). Honoured in login mode only.
  105:   static const explicitAccount = 'explicitAccount';
  106: 
  107:   /// The account [options] goes out with: [account] is the one its role
  108:   /// resolved to (see ApiType), kept only when login mode is on and the
  109:   /// request needs it (or asks for it, see [explicitAccount]); otherwise
  110:   /// anonymous. [loginMode] defaults to the setting (tests pass it).
  111:   static Account bind(
  112:     Account account,
  113:     RequestOptions options, {
  114:     bool? loginMode,
  115:   }) {
  116:     if (account is LoginAccount &&
  117:         (!(loginMode ?? LoginPolicy.loginMode) ||
  118:             (!requiresAccount(options) &&
  119:                 options.extra[explicitAccount] != true))) {
  120:       return AnonymousAccount();
  121:     }
  122:     return account;
  123:   }
  124: 
  125:   /// Whether [path] is on the lists that may carry the account. For the
  126:   /// settings UI: the per-request checks in [requiresAccount] (csrf writes,
  127:   /// own-mid reads) can still attach the account to a path not listed here.
  128:   static bool isAccountPath(String path) =>
  129:       _accountApis.contains(path) || _recommendApis.contains(path);
  130: 
  131:   /// Whether [options] may carry the logged-in account. False means it is
  132:   /// sent anonymously even in login mode.
  133:   static bool requiresAccount(RequestOptions options) {
  134:     final path = options.path;
  135:     // gRPC requests are sent as `appBaseUrl + GrpcUrl.x`
  136:     final grpcPath = path.startsWith(HttpString.appBaseUrl)
  137:         ? path.substring(HttpString.appBaseUrl.length)
  138:         : path;
  139:     if (_accountApis.contains(path) ||
  140:         _recommendApis.contains(path) ||
  141:         _grpcAccountApis.contains(grpcPath) ||
  142:         _grpcAccountPrefixes.any(grpcPath.startsWith)) {
  143:       return true;
  144:     }
  145:     final query = options.queryParameters;
  146:     final data = options.data;
  147:     // web writes are csrf-protected (some GET reads also carry csrf; they
  148:     // are not writes and stay anonymous)
  149:     if (options.method.toUpperCase() != 'GET' &&
  150:         (query.keys.any(_csrfKeys.contains) ||
  151:             (data is Map && data.keys.any(_csrfKeys.contains)) ||
  152:             (data is FormData &&
  153:                 data.fields.any((e) => _csrfKeys.contains(e.key))))) {
  154:       return true;
  155:     }
  156:     // reads scoped to the user themself (own space, own followings...)
  157:     final mid = Accounts.main.mid;
  158:     if (mid != 0) {
  159:       for (final key in _selfKeys) {
  160:         final v = query[key] ?? (data is Map ? data[key] : null);
  161:         if (v != null && '$v' == '$mid') return true;
  162:       }
  163:     }
  164:     return false;
  165:   }
  166: }
