--- lib/utils/mp4_join.dart
    1: part of 'mp4_remux.dart';
    2: 
    3: /// LibrePili: joins progressive MP4 segments (old single-URL downloads that
    4: /// come split into several files) into one timeline for [Mp4Remuxer]'s
    5: /// writer. Samples are read from each segment's sample tables (stts, ctts,
    6: /// stss, stsc, stsz/stz2, stco/co64) and copied byte-for-byte.
    7: ///
    8: /// Every segment must carry the same tracks (same kind and codec); a codec
    9: /// configuration (stsd) that differs between segments is kept as an extra
   10: /// sample entry, which chunks of that segment point at, and a differing
   11: /// media timescale is converted. Only different tracks or codecs throw
   12: /// [UnsupportedError], and the caller keeps the segments as separate files.
   13: abstract final class _Mp4Joiner {
   14:   static List<_Track> join(List<String> inputs) {
   15:     final tracks = _readProgressive(inputs.first);
   16:     for (final t in tracks) {
   17:       _openEndedEdits(t);
   18:     }
   19:     for (final input in inputs.skip(1)) {
   20:       final segment = _readProgressive(input);
   21:       if (segment.length != tracks.length) {
   22:         throw UnsupportedError('segments have different tracks: $input');
   23:       }
   24:       for (var i = 0; i < tracks.length; i++) {
   25:         final t = tracks[i];
   26:         final s = segment[i];
   27:         if (!_sameBytes(_handlerType(t), _handlerType(s))) {
   28:           throw UnsupportedError('segments have different tracks: $input');
   29:         }
   30:         if (s.sampleEntryType != t.sampleEntryType) {
   31:           throw UnsupportedError(
   32:             'codec changes between segments '
   33:             '(${t.sampleEntryType} -> …9293 tokens truncated…s also
   26:     // runs on text from danmaku / subtitles
   27:     List<int> split = data
   28:         .split(_splitRegex)
   29:         .reversed
   30:         .map((e) => int.tryParse(e) ?? 0)
   31:         .toList();
   32:     int duration = 0;
   33:     for (int i = 0; i < split.length; i++) {
   34:       duration += split[i] * pow(60, i).toInt();
   35:     }
   36:     return duration;
   37:   }
   38: 
   39:   static String formatDurationBetween(int startMillis, int endMillis) =>
   40:       formatTimeDuration(Duration(milliseconds: endMillis - startMillis));
   41: 
   42:   static String formatTimeDuration(Duration duration) {
   43:     final inDays = duration.inDays;
   44:     final daysLeft = inDays % 365;
   45:     final years = inDays ~/ 365;
   46:     final months = daysLeft ~/ 30;
   47:     final days = daysLeft % 30;
   48:     final hours = duration.inHours % 24;
   49:     final minutes = duration.inMinutes % 60;
   50: 
   51:     final format = StringBuffer();
   52: 
   53:     if (years > 0) format.write('$years年');
   54:     if (months > 0) format.write('$months月');
   55:     if (days > 0) format.write('$days天');
   56:     if (hours > 0) format.write('$hours小时');
   57:     if (minutes > 0) format.write('$minutes分钟');
   58: 
   59:     return format.toString();
   60:   }
   61: }
