   22:   WebDav._internal();
   23:   static final WebDav _instance = WebDav._internal();
   24:   factory WebDav() => _instance;
   25: 
   26:   _WebDavConfig _getConfig() {
   27:     String directory = Pref.webdavDirectory;
   28:     if (!directory.endsWith('/')) {
   29:       directory += '/';
   30:     }
   31:     return (
   32:       uri: Pref.webdavUri,
   33:       username: Pref.webdavUsername,
   34:       password: Pref.webdavPassword,
   35:       directory: '$directory${Constants.appName}',
   36:     );
   37:   }
   38: 
   39:   Future<webdav.Client> _connect(
   40:     _WebDavConfig config, {
   41:     bool force = false,
   42:   }) async {
   43:     final cachedClient = _client;
   44:     if (!force && cachedClient != null && _clientConfig == config) {
   45:       return cachedClient;
   46:     }
   47: 
   48:     final client =
   49:         webdav.newClient(
   50:             config.uri,
   51:             user: config.username,
   52:             password: config.password,
   53:           )
   54:           ..setHeaders({'accept-charset': 'utf-8'})
   55:           ..setConnectTimeout(12000)
   56:           ..setReceiveTimeout(12000)
   57:           ..setSendTimeout(12000);
   58: 
   59:     await client.mkdirAll(config.directory);
   60:     _clientConfig = config;
   61:     _client = client;
   62:     return client;
   63:   }
   64: 
   65:   Future<Pair<bool, String?>> init() async {
   66:     try {
   67:       await _connect(_getConfig(), force: true);
   68: 
   69:       return Pair(first: true, second: null);
   70:     } catch (e) {
   71:       return Pair(first: false, second: e.toString());
   72:     }
   73:   }
   74: 
   75:   String _getFileName() {
   76:     return 'piliplus_settings_${DeviceUtils.platformName}.json';
   77:   }
   78: 
   79:   Future<void> backup({bool includeCredentials = false}) async {
   80:     // Keep the payload bound to the same settings snapshot as the connection.
   81:     final config = _getConfig();
   82:     final data = GStorage.exportAllSettings(
   83:       includeCredentials: includeCredentials,
   84:     );
   85:     final webdav.Client client;
   86:     try {
   87:       client = await _connect(config);
   88:     } catch (e) {
   89:       SmartDialog.showToast('备份失败，请检查配置: $e');
   90:       return;
   91:     }
   92:     final path = '${config.directory}/${_getFileName()}';
