/// Schemes that read local content or run script: a url from a deep link /
/// a web page must not make the OS open `file:///…/hive/account.hive`.
/// App schemes (`weixin://`, `alipays://`…) stay allowed: handing those to
/// another app is what this is for.
static const _localSchemes = {
  'file',
  'content',
  'javascript',
  'data',
  'blob',
  'about',
  'filesystem',
};

static Future<void> launchURL(
  String url, {
  LaunchMode mode = LaunchMode.externalApplication,
}) async {
  try {
    final uri = Uri.parse(url);
    if (_localSchemes.contains(uri.scheme.toLowerCase())) {
      SmartDialog.showToast('已拦截: $url');
      return;
    }
    if (!await launchUrl(uri, mode: mode)) {
      SmartDialog.showToast('Could not launch $url');
    }
  } catch (e) {
    SmartDialog.showToast(e.toString());
  }
}

