import 'package:PiliPlus/http/retry_interceptor.dart';
import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';

class _CountingInterceptor extends Interceptor {
  int errors = 0;
  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    errors++;
    handler.next(err);
  }
}

class _FailAdapter implements HttpClientAdapter {
  int calls = 0;
  @override
  void close({bool force = false}) {}
  @override
  Future<ResponseBody> fetch(RequestOptions o, Stream<List<int>>? s,
      Future<void>? c) {
    calls++;
    throw DioException.connectionError(requestOptions: o, reason: 'probe');
  }
}

Future<(int, int, Object?)> run(String method, int count) async {
  final dio = Dio();
  final adapter = _FailAdapter();
  dio.httpClientAdapter = adapter;
  final counter = _CountingInterceptor();
  dio.interceptors.add(RetryInterceptor(dio, count, 1));
  dio.interceptors.add(counter);
  Object? thrown;
  try {
    await dio.fetch(RequestOptions(path: 'http://127.0.0.1:1/p', method: method));
  } catch (e) {
    thrown = e;
  }
  return (adapter.calls, counter.errors, thrown);
}

void main() {
  test('a retried GET reaches the following interceptors exactly once', () async {
    final (calls, seen, thrown) = await run('GET', 2);
    // ignore: avoid_print
    print('GET  retry=2 -> adapter=$calls following-onError=$seen');
    expect(calls, 3);
    expect(seen, 1);
    expect(thrown, isA<DioException>());
  });

  test('a GET that is not retried still reaches them once', () async {
    final (calls, seen, _) = await run('GET', 0);
    // ignore: avoid_print
    print('GET  retry=0 -> adapter=$calls following-onError=$seen');
    expect(calls, 1);
    expect(seen, 1);
  });

  test('a POST is not retried and still reaches them once', () async {
    final (calls, seen, _) = await run('POST', 2);
    // ignore: avoid_print
    print('POST retry=2 -> adapter=$calls following-onError=$seen');
    expect(calls, 1);
    expect(seen, 1);
  });
}
